// A nonce ends up both as a DOM attribute and inside doc.write'd markup, so only a
// conservative token charset is accepted — anything else could close the attribute and
// inject markup into the bootstrapped document. This is the base64 alphabet plus the
// url-safe variants real generators emit.
const CSP_NONCE_PATTERN = /^[A-Za-z0-9+/=_-]{1,256}$/;

const sanitizeCSPNonce = (nonce) => {
  if (typeof nonce !== 'string') {
    return null;
  }
  const trimmed = nonce.trim();
  return CSP_NONCE_PATTERN.test(trimmed) ? trimmed : null;
};

/**
 * Reads the nonce off the SDK's own <script> tag.
 *
 * `document.currentScript` is only non-null while the SDK script is running synchronously,
 * so this must be called at module-evaluation time (see gleapDetectedCSPNonce below) and
 * never lazily. Loaders that leave it null (type="module", injected-then-executed later)
 * fall back to locating the SDK tag by src.
 *
 * The nonce is read from the IDL property FIRST: browsers hide the content attribute once
 * the policy is applied, so getAttribute('nonce') returns "" on exactly the strict-CSP
 * pages this exists for. getAttribute is only a fallback for the non-CSP case.
 */
const detectCSPNonce = () => {
  try {
    if (typeof document === 'undefined') {
      return null;
    }

    const currentScript = document.currentScript;
    if (currentScript) {
      const nonce = sanitizeCSPNonce(currentScript.nonce || currentScript.getAttribute('nonce'));
      if (nonce) {
        return nonce;
      }
    }

    const sdkScript = document.querySelector('script[src*="sdk.gleap.io"]');
    if (sdkScript) {
      return sanitizeCSPNonce(sdkScript.nonce || sdkScript.getAttribute('nonce'));
    }
  } catch (exp) {}
  return null;
};

// Captured during the SDK script's own synchronous execution — do not move this below.
const gleapDetectedCSPNonce = detectCSPNonce();

// Set via Gleap.setCSPNonce() and always preferred over the auto-detected value, for
// loaders (tag managers, bundlers) that cannot put the nonce on the SDK tag itself.
let gleapConfiguredCSPNonce = null;

/**
 * Sets the CSP nonce the SDK stamps onto every <script>/<style> element it creates.
 * @param {string} nonce - the nonce from the page's Content-Security-Policy
 */
export const setGleapCSPNonce = (nonce) => {
  gleapConfiguredCSPNonce = sanitizeCSPNonce(nonce);
};

export const getGleapCSPNonce = () => {
  return gleapConfiguredCSPNonce || gleapDetectedCSPNonce;
};

/**
 * Stamps the page's nonce onto a <script>/<style> element the SDK created.
 * No-op when there is no nonce, so non-CSP pages keep byte-identical markup.
 * @param {HTMLElement} element
 * @returns {HTMLElement} the same element, for chaining
 */
export const applyGleapCSPNonce = (element) => {
  const nonce = getGleapCSPNonce();
  if (!nonce || !element) {
    return element;
  }

  try {
    // Both, deliberately: the content attribute is what older browsers match on, the
    // IDL property is what current ones read after nonce-hiding clears the attribute.
    element.setAttribute('nonce', nonce);
    element.nonce = nonce;
  } catch (exp) {}

  return element;
};

/**
 * Adds nonce="..." to every <script>/<style> tag in an HTML string.
 *
 * Needed because doc.write'd tags are parser-inserted: 'strict-dynamic' trust only
 * propagates through createElement() + appendChild(), and it makes the browser ignore
 * host allowlists entirely — so on a strict policy a nonce is the only source
 * expression that can let the app bundle execute.
 *
 * @param {string} html
 * @param {string} nonce - already sanitized
 * @returns {string}
 */
const stampNonceOnMarkup = (html, nonce) => {
  if (!nonce) {
    return html;
  }
  // The lookahead keeps a tag that already carries a nonce untouched.
  return html.replace(/<(script|style)\b(?![^>]*\snonce\s*=)/gi, '<$1 nonce="' + nonce + '"');
};

const CSP_DOCS_URL = 'https://docs.gleap.ai/documentation/javascript/content-security-policy';

// One warn per blocked resource/directive pair per page load — a frame can violate the
// same rule repeatedly (several assets, reconnect attempts), and repeating the warning
// would drown out the console we are trying to help debug.
const reportedFrameLoadIssues = new Set();

/**
 * Surfaces Content-Security-Policy blocks from inside a Gleap-bootstrapped frame.
 *
 * The about:blank frame inherits the host page's CSP, so a policy missing a Gleap origin
 * blocks the messenger's script, stylesheet or websocket with no signal from Gleap — the
 * launcher simply never appears. The violation events fire on the frame's document (they
 * don't reach the parent), so this listener is the only place they can be observed.
 *
 * @param {Document} doc - the frame document, right after doc.open() (open() clears listeners)
 * @param {{ baseHref: string, onBlocked: Function }} [fallback] - when the host policy blocks the
 *   frame's own script or stylesheet from the Gleap origin, onBlocked is called (once) so the
 *   caller can load the frame directly instead: a cross-origin iframe.src load is only subject to
 *   the host's frame-src, not its script-src/style-src.
 * @returns {void}
 */
export const warnOnCSPViolation = (doc, fallback) => {
  let fallbackTriggered = false;
  try {
    doc.addEventListener('securitypolicyviolation', (event) => {
      // Report-Only policies fire violations too but don't block anything.
      if (!event || event.disposition === 'report') {
        return;
      }
      const blockedURI = event.blockedURI || 'a resource';
      const directive = event.effectiveDirective || event.violatedDirective || 'unknown directive';
      const key = blockedURI + '|' + directive;
      if (!reportedFrameLoadIssues.has(key)) {
        reportedFrameLoadIssues.add(key);
        console.warn(
          "Gleap: Your page's Content-Security-Policy blocked " +
            blockedURI +
            ' (' +
            directive +
            '). Gleap may not appear or work correctly until your policy allows it — see ' +
            CSP_DOCS_URL
        );
      }

      if (
        fallback &&
        !fallbackTriggered &&
        isFrameSourceDirective(directive) &&
        typeof blockedURI === 'string' &&
        blockedURI.indexOf(fallback.baseHref) === 0
      ) {
        fallbackTriggered = true;
        fallback.onBlocked();
      }
    });
  } catch (e) {}
};

// Dispatched on the <iframe> element by the route script written into a bootstrapped frame when
// history.replaceState could not set the app route (exported for tests).
export const ROUTE_FAILED_EVENT = 'gleap-frame-route-failed';

// The directives that decide whether the bootstrapped frame's own bundle and stylesheet run.
const isFrameSourceDirective = (directive) =>
  typeof directive === 'string' && (directive.indexOf('script-src') === 0 || directive.indexOf('style-src') === 0);

/**
 * Whether the host document is a regular web page. Desktop shells (Electron `file://`, custom
 * app schemes) and hybrid containers (`capacitor://`, `ionic://`) are not.
 * @returns {boolean}
 */
export const isHttpDocument = () => {
  try {
    const protocol = window.location?.protocol;
    return protocol === 'http:' || protocol === 'https:';
  } catch (e) {
    return false;
  }
};

/**
 * Bootstraps an iframe by injecting a Gleap-hosted HTML document via about:blank + doc.write,
 * so the iframe inherits the parent page's origin instead of being a cross-site iframe to a
 * classified tracker domain.
 *
 * Why: Safari ITP applies restrictions (storage block, classification-based heuristics) to
 * iframes whose src is a classified tracker domain. By creating the iframe as about:blank and
 * writing the document content from the parent, the iframe becomes same-origin to the parent,
 * which Safari treats as first-party. The scripts inside the iframe still load from the
 * original Gleap origin, but as cross-origin script loads (not iframe navigations), which
 * ITP does not throttle.
 *
 * Requirements: the Gleap origin must serve the index.html with CORS (Access-Control-Allow-Origin).
 * `messenger-app.gleap.io` already does. For `outboundmedia.gleap.io` the helper will fall back
 * to direct iframe.src loading until CORS is enabled there.
 *
 * @param {HTMLIFrameElement} iframe - the iframe element (must already be appended to the DOM)
 * @param {string} url - the Gleap origin URL (e.g. https://messenger-app.gleap.io). May include a path.
 * @returns {void}
 */
export const bootstrapGleapFrame = (iframe, url) => {
  if (!iframe || !url) {
    return;
  }

  // Idempotent: several of the checks below can conclude independently that the bootstrapped
  // document is unusable, and re-assigning src would reload a frame that is already on its way.
  let fellBackToSrc = false;
  const fallbackToSrc = () => {
    if (fellBackToSrc) {
      return;
    }
    fellBackToSrc = true;
    try {
      iframe.src = url;
    } catch (e) {}
  };

  // The about:blank trick only buys anything on a web page (Safari ITP, see above). Inside a
  // desktop shell or hybrid container the frame would inherit a file:// or app-scheme origin
  // with whatever CSP the shell ships, and the pathname rewrite below is not reliable there —
  // either failure leaves the frame blank with nothing in the console. Load it directly instead.
  if (!isHttpDocument()) {
    return fallbackToSrc();
  }

  try {
    if (!iframe.contentDocument) return fallbackToSrc();
  } catch (e) {
    return fallbackToSrc();
  }

  // The asset base is the URL's origin + any path (e.g. https://outboundmedia.gleap.io/modal/).
  // We need a trailing slash so root-relative URLs resolve correctly via <base>.
  let baseHref;
  try {
    const parsed = new URL(url);
    // For a URL like https://outboundmedia.gleap.io/modal, assets are served from the origin root,
    // not from /modal/. So we use the origin as base. The path is just the entry HTML.
    baseHref = parsed.origin + '/';
  } catch (e) {
    return fallbackToSrc();
  }

  fetch(url, { mode: 'cors', credentials: 'omit' })
    .then((response) => {
      if (!response.ok) {
        throw new Error('Bootstrap fetch failed: ' + response.status);
      }
      return response.text();
    })
    .then((html) => {
      // Rewrite root-relative URLs (href="/x", src="/x") to absolute URLs on the Gleap origin,
      // so that the about:blank document (which has no base URL) can still resolve them.
      const absolutized = html.replace(/(\s(?:href|src)\s*=\s*["'])\/([^"'/][^"']*)/g, '$1' + baseHref + '$2');

      // The about:blank document is same-origin to the parent, so it INHERITS the parent's
      // CSP — the app's own <script src="...main.[hash].js"> is checked against the host
      // page's policy, not against messenger-app.gleap.io's. Stamp the page's nonce onto it
      // so a strict (nonce + 'strict-dynamic') policy can admit it. No-op without a nonce.
      const nonce = getGleapCSPNonce();
      const noncedHtml = stampNonceOnMarkup(absolutized, nonce);
      const nonceAttr = nonce ? ' nonce="' + nonce + '"' : '';

      // The Gleap apps (banner, modal, agent-conversation, chatbar) are SPAs that route based
      // on window.location.pathname. Since the iframe inherits the parent's origin via about:blank,
      // pathname would be the parent page's pathname — not the intended app route.
      // We use history.replaceState() to set the iframe's URL to the intended path BEFORE the
      // app's router initializes. replaceState is allowed because the iframe is same-origin to the parent.
      let targetPath = '/';
      let targetPathname = '/';
      try {
        const parsedTarget = new URL(url);
        targetPathname = parsedTarget.pathname;
        targetPath = targetPathname + parsedTarget.search + parsedTarget.hash;
      } catch (e) {}
      // If the rewrite did not land on the intended pathname — sandboxed/exotic origins throw,
      // and on Windows a file:///C:/... base keeps the drive letter, so "/modal" resolves to
      // "/C:/modal" (Gleap #146130) — the app's router would match nothing and the frame would stay blank — so the script also checks
      // the outcome and raises ROUTE_FAILED_EVENT on its own <iframe> element for the parent.
      const routeScript =
        '<script' +
        nonceAttr +
        '>try{history.replaceState(null,"",' +
        JSON.stringify(targetPath) +
        ');}catch(e){}' +
        'try{if(location.pathname!==' +
        JSON.stringify(targetPathname) +
        '&&window.frameElement){window.frameElement.dispatchEvent(new Event(' +
        JSON.stringify(ROUTE_FAILED_EVENT) +
        '));}}catch(e){}</script>';

      // Inject the route-setter script BEFORE the first existing <script> tag so it runs
      // before any app bundle. If no <script> is found, inject just before </head> as a fallback.
      let withRouteScript;
      if (/<script\b/i.test(noncedHtml)) {
        withRouteScript = noncedHtml.replace(/<script\b/i, routeScript + '<script');
      } else if (/<\/head>/i.test(noncedHtml)) {
        withRouteScript = noncedHtml.replace(/<\/head>/i, routeScript + '</head>');
      } else {
        withRouteScript = noncedHtml;
      }

      // Re-grab contentDocument here — Firefox may have replaced the initial about:blank
      // document during the fetch. Writing into the original reference would be a silent no-op.
      let doc;
      try {
        doc = iframe.contentDocument;
      } catch (e) {
        return fallbackToSrc();
      }
      if (!doc) {
        return fallbackToSrc();
      }

      // Raised by the route script when the pathname rewrite did not take (see above). Listening
      // on the element rather than reading the frame's pathname after doc.write keeps this
      // correct whether the parser runs the inline script synchronously or a tick later.
      try {
        iframe.addEventListener(ROUTE_FAILED_EVENT, fallbackToSrc, { once: true });
      } catch (e) {}

      try {
        doc.open();
        // After open(), which wipes any existing listeners. The violation events for the
        // written markup are fired from queued tasks, so attaching here catches them all.
        // A blocked bundle or stylesheet means the written document can never render; the
        // hook switches to a direct src load, which the host's script-src does not govern.
        warnOnCSPViolation(doc, { baseHref, onBlocked: fallbackToSrc });
        doc.write(withRouteScript);
        doc.close();
      } catch (e) {
        fallbackToSrc();
      }
    })
    .catch((error) => {
      // CORS error, network error, non-OK status — or the host page's CSP blocking the
      // fetch (connect-src): fall back to direct iframe.src loading. The fallback keeps
      // working setups working, but under a blocking CSP it fails too, with nothing in
      // the console pointing at Gleap — so name the failure once before falling back.
      if (!reportedFrameLoadIssues.has(url)) {
        reportedFrameLoadIssues.add(url);
        console.warn(
          'Gleap: Loading ' +
            url +
            ' failed (' +
            (error && error.message ? error.message : 'network error') +
            ') — falling back to loading the frame directly. If Gleap does not appear, your ' +
            "Content-Security-Policy may be blocking it (most often a missing connect-src entry) — see " +
            CSP_DOCS_URL
        );
      }
      fallbackToSrc();
    });
};

export const resizeImage = (base64Str, maxWidth = 400, maxHeight = 400) => {
  return new Promise((resolve, reject) => {
    var isJPEG = base64Str.indexOf('data:image/jpeg') === 0;
    var img = new Image();
    img.src = base64Str;
    img.onerror = () => {
      reject();
    };
    img.onload = () => {
      var canvas = document.createElement('canvas');
      var MAX_WIDTH = maxWidth;
      var MAX_HEIGHT = maxHeight;

      // Adjust max width / height based on image props
      if (maxWidth > img.width / 1.5) {
        MAX_WIDTH = img.width / 1.5;
      }

      if (maxHeight > img.height / 1.5) {
        MAX_HEIGHT = img.height / 1.5;
      }

      var width = img.width;
      var height = img.height;

      if (width > height) {
        if (width > MAX_WIDTH) {
          height *= MAX_WIDTH / width;
          width = MAX_WIDTH;
        }
      } else {
        if (height > MAX_HEIGHT) {
          width *= MAX_HEIGHT / height;
          height = MAX_HEIGHT;
        }
      }
      canvas.width = width;
      canvas.height = height;
      var ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, width, height);

      if (isJPEG) {
        resolve(canvas.toDataURL('image/jpeg', 0.7));
      } else {
        resolve(canvas.toDataURL());
      }
    };
  });
};

const MOBILE_UA_REGEX = /(android|iphone|ipod|ipad|blackberry|iemobile|opera mini|webos)/i;

export const getDeviceType = () => {
  return isMobile() ? 'mobile' : 'desktop';
};

export const isMobile = () => {
  if (typeof window === 'undefined') {
    return false;
  }

  try {
    const nav = typeof navigator !== 'undefined' ? navigator : undefined;

    if (nav?.userAgentData && typeof nav.userAgentData.mobile === 'boolean' && nav.userAgentData.mobile !== null) {
      return nav.userAgentData.mobile;
    }

    if (nav && MOBILE_UA_REGEX.test(nav.userAgent || nav.vendor || '')) {
      return true;
    }

    if (nav?.maxTouchPoints > 1 && window.matchMedia) {
      const coarsePointer = window.matchMedia('(hover: none) and (pointer: coarse)');
      if (coarsePointer?.matches) {
        return true;
      }
    }
  } catch (exp) {
    // Swallow errors and treat as desktop fallback.
  }

  return false;
};

export const gleapDataParser = function (data) {
  if (!data) {
    return {};
  }
  if (typeof data === 'string' || data instanceof String) {
    try {
      return JSON.parse(data);
    } catch (e) {
      return {};
    }
  }
  return data;
};

// Coerce a company id/name into a usable string, or null if it cannot be one.
// Only primitives that stringify meaningfully are accepted: objects and arrays
// would turn into "[object Object]" / "a,b", which is never a real identifier.
const normalizeCompanyValue = (value) => {
  if (typeof value === 'string') {
    // Return the TRIMMED value, not the original: the server matches companyId
    // byte-for-byte, so " acme " and "acme" would become two separate companies.
    const trimmed = value.trim();
    return trimmed.length > 0 ? trimmed : null;
  }
  if (typeof value === 'number') {
    return Number.isFinite(value) ? String(value) : null;
  }
  if (typeof value === 'bigint') {
    return String(value);
  }
  return null;
};

// Map ergonomic { company: { id, name } } to the flat companyId/companyName fields.
// The raw `company` key must never survive into the outgoing payload: the server
// does not know it as a session field, so it ends up either as a stray customData
// attribute or as an unset that the client-side dedup can never match - which
// re-fires /sessions/identify on every single identify call.
export const flattenCompany = (userData) => {
  try {
    if (!userData || typeof userData !== 'object' || !('company' in userData)) {
      // Nothing to do - hand back the exact same reference (no-op).
      return userData;
    }

    const company = userData.company;
    const out = { ...userData };
    delete out.company;

    if (!company || typeof company !== 'object') {
      return out;
    }

    const companyId = normalizeCompanyValue(company.id);
    if (!companyId) {
      // Without an id the server cannot create/link the company, and a name
      // alone would show a company the contact is not actually linked to.
      return out;
    }

    out.companyId = companyId;

    const companyName = normalizeCompanyValue(company.name);
    if (companyName) {
      out.companyName = companyName;
    }

    return out;
  } catch (exp) {
    // This runs in customer browsers - never break the widget over user data.
    return userData;
  }
};

// Ordered smallest-to-largest, each entry holding how many of the current unit
// fit into the next one. Walking the list promotes the value to the largest
// unit it still fills, so 90 minutes reads as "1 hour", not "90 minutes".
//
// Seconds are deliberately absent: anything under a minute collapses to "now"
// (see below) rather than ticking "9 seconds ago", which reads as noise on a
// notification the user is looking at right now.
const RELATIVE_TIME_DIVISIONS = [
  { amount: 60, unit: 'minute' },
  { amount: 24, unit: 'hour' },
  { amount: 7, unit: 'day' },
  { amount: 4.34524, unit: 'week' },
  { amount: 12, unit: 'month' },
  { amount: Number.POSITIVE_INFINITY, unit: 'year' },
];

/**
 * "now" / "5 minutes ago" label for a notification's age, localized by the
 * browser through Intl.RelativeTimeFormat — the SDK ships no date library and
 * this needs to read correctly in every language the messenger supports.
 *
 * Returns '' whenever a truthful label can't be produced (no timestamp, an
 * unparsable one, or a browser without the API), so callers can drop the
 * separator instead of printing a placeholder.
 *
 * @param {string|number|Date} value - the moment the notification was sent
 * @param {string} [locale] - BCP-47 tag; falls back to the browser's locale
 * @returns {string}
 */
export const formatRelativeTime = (value, locale) => {
  try {
    if (!value || typeof Intl === 'undefined' || typeof Intl.RelativeTimeFormat !== 'function') {
      return '';
    }

    const timestamp = new Date(value).getTime();
    if (isNaN(timestamp)) {
      return '';
    }

    // The locale comes from the page's lang attribute / the SDK's language
    // override, so it can be a tag Intl rejects. Falling back to the browser's
    // own locale keeps the label rather than dropping it.
    let formatter;
    try {
      formatter = new Intl.RelativeTimeFormat(locale || undefined, { numeric: 'auto' });
    } catch (exp) {
      formatter = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' });
    }

    // Clamped at 0: a notification scheduled a few seconds ahead (or a client
    // clock running behind the server's) must never read as "in 1 minute".
    const seconds = Math.min(0, (timestamp - Date.now()) / 1000);

    // Under a minute is "now" ("just now" in the locales that phrase it that
    // way) — numeric: 'auto' turns the literal 0 into the word.
    if (seconds > -60) {
      return formatter.format(0, 'second');
    }

    let duration = seconds / 60;

    for (let i = 0; i < RELATIVE_TIME_DIVISIONS.length; i++) {
      const division = RELATIVE_TIME_DIVISIONS[i];
      if (Math.abs(duration) < division.amount) {
        return formatter.format(Math.round(duration), division.unit);
      }
      duration /= division.amount;
    }
  } catch (exp) {}

  return '';
};

export const truncateString = (str, num) => {
  if (str.length > num) {
    return str.slice(0, num) + '...';
  } else {
    return str;
  }
};

const removeSubDomain = (v) => {
  try {
    var parts = v.split('.');
    var is2ndLevelDomain = false;
    const secondLevel = parts[parts.length - 2];
    if (
      secondLevel === 'co' ||
      secondLevel === 'com' ||
      secondLevel === 'gv' ||
      secondLevel === 'ac' ||
      secondLevel === 'edu' ||
      secondLevel === 'gov' ||
      secondLevel === 'mil' ||
      secondLevel === 'net' ||
      secondLevel === 'org'
    ) {
      is2ndLevelDomain = true;
    }
    parts = parts.slice(is2ndLevelDomain ? -3 : -2);
    return parts.join('.');
  } catch (exp) {}
  return v;
};

export const loadFromGleapCache = (key) => {
  try {
    const cachedData = localStorage.getItem(`gleap-widget-${key}`);
    if (cachedData) {
      const config = JSON.parse(cachedData);
      return config;
    }
  } catch (exp) {}
  return null;
};

export const saveToGleapCache = (key, data) => {
  const k = `gleap-widget-${key}`;
  if (data) {
    try {
      localStorage.setItem(k, JSON.stringify(data));
    } catch (exp) {}
  } else {
    localStorage.removeItem(k);
  }
};

export const clearGleapCache = (key) => {
  try {
    const k = `gleap-widget-${key}`;
    localStorage.removeItem(k);
  } catch {}
};

export const setGleapCookie = (name, value, days) => {
  try {
    var expires = '';
    if (days) {
      var date = new Date();
      date.setTime(date.getTime() + days * 24 * 60 * 60 * 1000);
      expires = '; expires=' + date.toUTCString();
    }
    const host = removeSubDomain(window.location.host.split(':')[0]);
    document.cookie = name + '=' + (value || '') + expires + '; path=/; domain=' + host;
  } catch (exp) {}
};

export const getGleapCookie = (name) => {
  try {
    var nameEQ = name + '=';
    var ca = document.cookie.split(';');
    for (var i = 0; i < ca.length; i++) {
      var c = ca[i];
      while (c.charAt(0) == ' ') c = c.substring(1, c.length);
      if (c.indexOf(nameEQ) == 0) return c.substring(nameEQ.length, c.length);
    }
  } catch (exp) {}
  return null;
};

export const eraseGleapCookie = (name) => {
  try {
    const host = removeSubDomain(window.location.host.split(':')[0]);
    document.cookie = name + '=; Path=/; Expires=Thu, 01 Jan 1970 00:00:01 GMT; Domain=' + host;
  } catch (exp) {}
};

export const getDOMElementDescription = (element, html = true) => {
  var innerText = truncateString(element.innerText || '', 40)
    .replace(/(\r\n|\n|\r)/gm, '')
    .replace(/ +(?= )/g, '');
  var elementId = '';
  var elementClass = '';
  if (typeof element.getAttribute !== 'undefined') {
    const elemId = element.getAttribute('id');
    if (elemId) {
      elementId = ` id="${elemId}"`;
    }
    const elemClass = element.getAttribute('class');
    if (elemClass) {
      elementClass = ` class="${elemClass}"`;
    }
  }
  const elementTag = (element.tagName || '').toLowerCase();

  var htmlPre = '<';
  var htmlPost = '>';
  if (!html) {
    htmlPre = '[';
    htmlPost = ']';
  }

  return `${htmlPre}${elementTag}${elementId}${elementClass}${htmlPost}${innerText}${htmlPre}/${elementTag}${htmlPost}`;
};

export const runFunctionWhenDomIsReady = (callback) => {
  if (document.readyState === 'complete' || document.readyState === 'loaded' || document.readyState === 'interactive') {
    callback();
  } else {
    document.addEventListener('DOMContentLoaded', () => {
      callback();
    });
  }
};

// Bind the iOS keyboard viewport fix at most once per page session. Even though
// fixGleapHeight() is only called from Gleap.initialize() today, a SPA re-init
// must never stack a second set of visualViewport listeners — duplicates would
// fight each other on every event, which can leave the widget stuck shrunk.
let gleapHeightFixInstalled = false;

export const fixGleapHeight = () => {
  try {
    // Strict no-op off iOS / when the VisualViewport API is unavailable.
    if (!('visualViewport' in window) || !window.visualViewport || !/iPad|iPhone|iPod/.test(navigator.userAgent)) {
      return;
    }

    // Idempotent: install the listeners only once.
    if (gleapHeightFixInstalled) {
      return;
    }
    gleapHeightFixInstalled = true;

    // Minimum keyboard height that counts as "the keyboard is open". We detect
    // the keyboard as the gap between the LAYOUT viewport (window.innerHeight)
    // and the VISUAL viewport (visualViewport.height): on iOS the soft keyboard
    // shrinks ONLY the visual viewport, so innerHeight - visualViewport.height is
    // the keyboard height. Crucially, the iOS dynamic toolbar (address bar /
    // bottom bar) shrinks BOTH viewports together, so it leaves this gap at ~0 —
    // it can never be misread as a keyboard (measured on iPhone the toolbar moves
    // the viewport by ~160px, which a naive "shrunk vs full height" check would
    // wrongly treat as a keyboard and leave the widget stuck). Real iOS keyboards
    // are ~260px+; 150px sits in the safe valley above toolbar/rounding noise and
    // below the smallest real keyboard. Erring below the threshold always means
    // "treat as closed" (full size) — the safe direction that can never stick.
    const KEYBOARD_OPEN_THRESHOLD = 150;

    // iOS usually fires a single visualViewport 'resize' at the END of the
    // keyboard transition, and that value can still be mid-animation. Some
    // dismiss gestures fire no final event at all. So after every event we also
    // re-measure once, slightly later, to read the settled dimensions. This is
    // the self-correcting safety net that removes the styles even if no further
    // event arrives.
    const SETTLE_DELAY = 350;

    const round = (value) => Math.round(value);

    let settleTimer = null;
    let pendingUpdate = false;

    // Set true when the composer loses focus (e.g. when a message is sent, which
    // blurs the input) and no other input takes focus. While set, the keyboard is
    // treated as closed regardless of the visual viewport — iOS 26 sometimes does
    // NOT reset visualViewport.height/offsetTop after a dismiss (FB19889436), so
    // the resize-driven reset never fires and the widget would stay shrunk. This
    // is cleared the instant an input is focused again, so the keyboard can
    // re-open normally.
    let keyboardForcedClosed = false;

    // The iframe document we've attached focus listeners to (same-origin case).
    let keyboardFocusDoc = null;

    function measure() {
      try {
        const gleapFrameContainer = document.querySelector('.gleap-frame-container-inner iframe');

        if (!gleapFrameContainer) {
          return;
        }

        // Attach focus listeners to the (same-origin) iframe document so we get
        // a reliable "keyboard is closing" signal independent of the viewport.
        ensureKeyboardFocusListeners(gleapFrameContainer);

        const visualViewport = window.visualViewport;

        // Keyboard height = layout viewport - visual viewport. Read live every
        // time (never a stale once-captured baseline). Rounded so a fractional
        // visualViewport.height can't sit a sub-pixel below innerHeight and read
        // as open. Toolbar moves both viewports together -> gap ~0 -> closed.
        const keyboardHeight = round(window.innerHeight) - round(visualViewport.height);
        // keyboardForcedClosed wins so a stuck iOS 26 viewport can't keep the
        // widget shrunk after a send/dismiss (it's cleared on the next focus).
        const keyboardIsOpen = !keyboardForcedClosed && keyboardHeight >= KEYBOARD_OPEN_THRESHOLD;

        if (keyboardIsOpen) {
          gleapFrameContainer.style.setProperty('max-height', visualViewport.height + 'px', 'important');
          // When the keyboard opens, iOS pans the visual viewport up to reveal
          // the focused field. The widget is position:fixed (anchored to the
          // layout viewport), so without compensation it appears to "scroll up"
          // behind the status bar. Translate it down by the viewport offset to
          // keep it pinned to the visible area above the keyboard.
          gleapFrameContainer.style.setProperty('transform', 'translateY(' + visualViewport.offsetTop + 'px)', 'important');
        } else {
          // Reset in EVERY non-open path. removeProperty is idempotent and safe
          // even when nothing was set.
          gleapFrameContainer.style.removeProperty('max-height');
          gleapFrameContainer.style.removeProperty('transform');
        }
      } catch (error) {}
    }

    // When the composer loses focus (e.g. after sending a message, which blurs
    // the input) the keyboard is closing. iOS 26 sometimes leaves the visual
    // viewport shrunk/panned, so the resize-driven reset never fires and the
    // widget stays in the small "keyboard" size. Force the reset here and latch
    // keyboardForcedClosed so a stale viewport can't re-shrink until the next
    // focus. The short delay lets focus settle (so a blur that immediately
    // refocuses another field doesn't reset).
    function handleComposerBlur() {
      try {
        window.setTimeout(() => {
          try {
            const active = keyboardFocusDoc && keyboardFocusDoc.activeElement;
            if (active && (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA' || active.isContentEditable)) {
              return; // focus moved to another field — keyboard stays open
            }

            keyboardForcedClosed = true;

            const frame = document.querySelector('.gleap-frame-container-inner iframe');
            if (frame) {
              frame.style.removeProperty('max-height');
              frame.style.removeProperty('transform');
            }
            scheduleUpdate();
          } catch (innerError) {}
        }, 100);
      } catch (error) {}
    }

    function handleComposerFocus() {
      // A real focus means the keyboard is (re)opening; release the latch so
      // measure() is free to shrink again.
      keyboardForcedClosed = false;
      scheduleUpdate();
    }

    // Attach focus listeners to the iframe's own document. The widget iframe is
    // bootstrapped same-origin (about:blank + doc.write), so this works in the
    // common case; the legacy cross-origin src fallback throws on contentDocument
    // access (caught) and there we just rely on the viewport detection.
    function ensureKeyboardFocusListeners(frame) {
      try {
        const frameDoc = frame.contentDocument;
        if (!frameDoc || frameDoc === keyboardFocusDoc) {
          return;
        }
        keyboardFocusDoc = frameDoc;
        frameDoc.addEventListener('focusout', handleComposerBlur, true);
        frameDoc.addEventListener('focusin', handleComposerFocus, true);
      } catch (error) {}
    }

    // Coalesce simultaneous resize + scroll into a single update per frame
    // (canonical VisualViewport pattern), then arm a delayed settle re-check to
    // read the final post-animation dimensions.
    function scheduleUpdate() {
      try {
        if (!pendingUpdate) {
          pendingUpdate = true;
          window.requestAnimationFrame(() => {
            pendingUpdate = false;
            measure();
          });
        }

        if (settleTimer) {
          clearTimeout(settleTimer);
        }
        settleTimer = setTimeout(measure, SETTLE_DELAY);
      } catch (error) {}
    }

    function handleOrientationChange() {
      try {
        // innerHeight/visualViewport settle a bit after a rotation; the settle
        // timer re-checks with the gap method, which needs no per-orientation
        // baseline.
        scheduleUpdate();
      } catch (error) {}
    }

    const visualViewport = window.visualViewport;

    // Keyboard show/hide and viewport resizes.
    visualViewport.addEventListener('resize', scheduleUpdate);

    // Visual-viewport pan (offsetTop changes) while the keyboard animates in/out
    // so the widget stays aligned with the visible area.
    visualViewport.addEventListener('scroll', scheduleUpdate);

    // Re-check after orientation changes.
    window.addEventListener('orientationchange', handleOrientationChange);

    // Initial measure (no keyboard expected -> no-op).
    measure();
  } catch (error) {}
};
